    "source": "/// 0-1 knapsack brute force — complete Rust reference (capacity W is `cap`).\npub fn knapsack_brute(weights: &[usize], values: &[i64], cap: usize) -> i64 {\n    let n = weights.len();\n    let mut best = 0;\n    let total: u64 = 1 << n;\n    for mask in 0..total {\n        let mut wt = 0;\n        let mut val = 0;\n        for i in 0..n {\n            if mask & (1 << i) != 0 {\n                wt += weights[i];\n                val += values[i];\n            }\n        }\n        if wt <= cap && val > best {\n            best = val;\n        }\n    }\n    best\n}\n",
